# AUTO-GENERATED by Claude Code
# Purpose: runs the Smash knowledge eval dataset (smash_knowledge.yaml) against ds.ai.agent,
#          so docs/tool/prompt changes can be checked for regressions.
# Usage: uv run ds ai eval   (calls the OpenAI API for both the agent and the LLM judge)
# ---------------------------------------------------------------------------
from __future__ import annotations

from pathlib import Path
from typing import TYPE_CHECKING

from pydantic_evals import Dataset

if TYPE_CHECKING:
    from pydantic_evals.reporting import EvaluationReport

__all__ = ["KNOWLEDGE_DATASET", "load_knowledge_dataset", "run_knowledge_evals"]

KNOWLEDGE_DATASET = Path(__file__).parent / "smash_knowledge.yaml"


def load_knowledge_dataset() -> Dataset[str, str, dict]:
    """Load the question/expected-answer cases for the knowledge agent."""
    return Dataset[str, str, dict].from_file(KNOWLEDGE_DATASET)


async def _ask(question: str) -> str:
    # imported lazily so loading the dataset doesn't require building the agent
    from ds.ai.agent import agent

    result = await agent.run(question)
    return result.output


def run_knowledge_evals(name_filter: str = "") -> EvaluationReport:
    """Run every case (or those whose name contains name_filter) and return the report."""
    dataset = load_knowledge_dataset()
    if name_filter:
        dataset.cases = [c for c in dataset.cases if name_filter in (c.name or "")]
    return dataset.evaluate_sync(_ask, name="smash_knowledge")
